# fanout.py: which hosts touched many distinct peers on admin ports?
from collections import defaultdict

ADMIN_PORTS = {135, 445, 3389, 5985, 5986}   # RPC, SMB, RDP, WinRM
THRESHOLD = 10                                # distinct peers per window

def fanout(conns, window_s=600):
    peers = defaultdict(set)                  # (source, window) -> {dest}
    for ts, src, dst, port in conns:
        if port in ADMIN_PORTS:
            peers[(src, ts // window_s)].add(dst)
    return {k: len(v) for k, v in peers.items() if len(v) >= THRESHOLD}

conns = [
    (12, "laptop1", "fs01", 445), (40, "laptop1", "dc01", 445),
    (95, "laptop2", "fs01", 445), (130, "laptop3", "fs01", 445),
    (300, "laptop3", "dc01", 135),
]
conns += [(200 + i, "laptop7", f"10.0.1.{i}", 445) for i in range(1, 41)]
conns += [(100 + 9 * i, "backup01", f"srv{i:02d}", 445) for i in range(25)]
print(fanout(conns))
# {('laptop7', 0): 40, ('backup01', 0): 25}

# nftables on the DMZ web server: it may only start the connections its job needs
table inet egress {
  chain out {
    type filter hook output priority 0; policy drop;
    ct state established,related accept      # replies to inbound HTTPS
    oif "lo" accept
    ip daddr 10.0.20.15 tcp dport 5432 accept # the application's database
    ip daddr 10.0.0.53 udp dport 53 accept    # the internal DNS resolver
    log prefix "egress-drop " drop            # everything else: refused and logged
  }
}

# /etc/ssh/sshd_config.d/60-no-forwarding.conf on servers that are not jump hosts
DisableForwarding yes
